  (2, 'the-witcher-3-wild-hunt', 'jogo', 'jogos', 'The Witcher 3: Wild Hunt', 'The Witcher 3: Wild Hunt é um RPG de ação em mundo aberto, onde você joga como Geralt de Rívia, um caçador de monstros. Explore um vasto mundo cheio de missões, monstros e escolhas morais que afetam o destino do continente.', 'ativo', 129.99, 45.5, true, null, 292030, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['RPG', 'Mundo Aberto', 'Fantasia']::text[], 'CD PROJEKT RED', 2015, 'midia_fisica', 9.5, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/292030/1018852715/bf5e4c4a6409b1714754e691e778ae9f66ab9907/1790683068/hls_264_master.m3u8?t=1790693333","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257439641/32f72964eceaa2ea37c3ab03dff903a45414a89b/movie_600x337.jpg"}'::jsonb, array['f7f564ecedd09b3e503b071a637aeefdedbeedd8/ss_f7f564ecedd09b3e503b071a637aeefdedbeedd8', '0a38e4d0d57f15934772dbe09b322d08132d5518/ss_0a38e4d0d57f15934772dbe09b322d08132d5518', '19c03c2b997d3a393fc629fd42f55ddb4a3d8dd0/ss_19c03c2b997d3a393fc629fd42f55ddb4a3d8dd0', '3a3f430982cc3bccac1633d3ea60a30bf3d1ae9e/ss_3a3f430982cc3bccac1633d3ea60a30bf3d1ae9e', '78ecbfb8bc64b8e9d4a372f4a8ffa5069e9325d0/ss_78ecbfb8bc64b8e9d4a372f4a8ffa5069e9325d0', '203487f667e4ac00baf482b1c93c87a2b830a6fc/ss_203487f667e4ac00baf482b1c93c87a2b830a6fc']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/292030/94a3c7f9db82538b752312f6e17f912f0899ca30/page_bg_raw.jpg', null, true, null, '{}'::text[], '{}'::text[], null),
  (3, 'cyberpunk-2077', 'jogo', 'jogos', 'Cyberpunk 2077', 'Cyberpunk 2077 é um RPG de ação em mundo aberto ambientado na distópica Night City. Você joga como V, um mercenário em busca de um implante único que concede a imortalidade. Explore a cidade, faça escolhas morais e enfrente gangues e corporações poderosas.', 'ativo', 199.9, 99.95, true, null, 1091500, array['PS5', 'Xbox Series X/S']::text[], array['RPG', 'Ação', 'Mundo Aberto', 'Ficção Científica']::text[], 'CD PROJEKT RED', 2020, 'midia_fisica', 8.6, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1091500/798578/0d0c54b81225b2b7760d1a99b6c5950cb85a1767/1750617872/hls_264_master.m3u8?t=1734434783","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257081132/885331d24a8e88a0a90903f588835ed38b2f82cf/movie_600x337.jpg"}'::jsonb, array['ss_2f649b68d579bf87011487d29bc4ccbfdd97d34f', 'ss_0e64170751e1ae20ff8fdb7001a8892fd48260e7', 'ss_af2804aa4bf35d4251043744412ce3b359a125ef', 'ss_7924f64b6e5d586a80418c9896a1c92881a7905b', 'ss_4eb068b1cf52c91b57157b84bed18a186ed7714b', 'ss_b529b0abc43f55fc23fe8058eddb6e37c9629a6a']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1091500/644eb087007768417a847e52c38eeaf34b57fd12/page_bg_raw.jpg', null, true, null, '{}'::text[], '{}'::text[], null),
  (4, 'batman-arkham-knight', 'jogo', 'jogos', 'Batman: Arkham Knight', 'Batman: Arkham Knight é um jogo de ação e aventura em mundo aberto, onde você assume o papel do Cavaleiro das Trevas. Explore Gotham City, enfrente vilões icônicos e utilize gadgets para combater o crime nesta emocionante história.', 'ativo', 69.99, 14, true, null, 208650, array['PS4']::text[], array['Ação', 'Aventura', 'Super-herói']::text[], 'Rocksteady Studios', 2015, 'midia_fisica', 8, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/208650/33605/48fb1c9f09bee1d57ac8d8a29236ed26b07f9e19/1750493315/hls_264_master.m3u8?t=1447372011","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2038213/movie.293x165.jpg"}'::jsonb, array['ss_90026e46a995760d53bfa2dc1612b73960c84c94', 'ss_4c9d5fb849b1a7169184a37db000919b276056fe', 'ss_5da3185e4f7da999300555747be6b84b8f16164f', 'ss_43ac2ec5dc64f59b1816b1cc0ba5b430d36c636f', 'ss_88b07767c3d67b3d5be85fb27c97527770a98e7e', 'ss_0093e9b8191093a1c97187079adb3d93a8ba6cf9']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/208650', null, false, null, '{}'::text[], '{}'::text[], null),
  (5, 'red-dead-redemption-2', 'jogo', 'jogos', 'Red Dead Redemption 2', 'Red Dead Redemption 2 é um jogo de ação e aventura em mundo aberto ambientado no Velho Oeste. Você joga como Arthur Morgan, um fora da lei, enquanto explora vastas paisagens, enfrenta gangues rivais e toma decisões que moldam a história.', 'ativo', 299.9, 98.97, true, null, 1174180, array['PS4']::text[], array['Ação', 'Aventura', 'Mundo Aberto', 'Faroeste']::text[], 'Rockstar Games', 2018, 'midia_fisica', 9.7, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1174180/254564/0c67cc67d242324fc1ddda31dceb2a814e009c5b/1750634104/hls_264_master.m3u8?t=1574881606","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256768244/movie.293x165.jpg"}'::jsonb, array['ss_66b553f4c209476d3e4ce25fa4714002cc914c4f', 'ss_bac60bacbf5da8945103648c08d27d5e202444ca', 'ss_668dafe477743f8b50b818d5bbfcec669e9ba93e', 'ss_4ce07ae360b166f0f650e9a895a3b4b7bf15e34f', 'ss_d1a8f5a69155c3186c65d1da90491fcfd43663d9']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1174180/page_bg_raw.jpg', null, true, null, '{}'::text[], '{}'::text[], null),
  (6, 'grand-theft-auto-v', 'jogo', 'jogos', 'Grand Theft Auto V', 'Grand Theft Auto V é um jogo de ação e aventura em mundo aberto, onde você pode explorar a cidade fictícia de Los Santos. Assuma o controle de três protagonistas, participe de missões emocionantes, conduza veículos e mergulhe em uma narrativa envolvente cheia de crime e intriga.', 'ativo', 99.9, 59.94, true, null, 3240220, array['PS5', 'PS4', 'PS3', 'Xbox Series X/S', 'Xbox 360']::text[], array['Ação', 'Mundo Aberto', 'Tiro']::text[], 'Rockstar North', 2013, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/3240220/478153532/b74a7322cbaece3aac7ef4f5a07d498d92d1633b/1765478654/hls_264_master.m3u8?t=1765479639","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257247680/6953f3f3d5ff4750a447fd604910cb5a2eb19a35/movie_600x337.jpg"}'::jsonb, array['d61184a98c1cf2db2b08b2999c04b0519e3615bb/ss_d61184a98c1cf2db2b08b2999c04b0519e3615bb', '8340fd391012e12be7e4c02e65801a2648a6b60e/ss_8340fd391012e12be7e4c02e65801a2648a6b60e', 'f2e70b5823510daa062293ff0b03821e1dee2d37/ss_f2e70b5823510daa062293ff0b03821e1dee2d37', '6959cc5d64cce82cb68a27457cfa46fb4d50f897/ss_6959cc5d64cce82cb68a27457cfa46fb4d50f897', '0231bf16835cd4f6d83523d76aa8d91cb2dfef9b/ss_0231bf16835cd4f6d83523d76aa8d91cb2dfef9b', '60690d0fdbd022ab1527ba6d080d42c1812a0f39/ss_60690d0fdbd022ab1527ba6d080d42c1812a0f39']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3240220/page_bg_raw.jpg', '{"destaque":"https://cdn.cloudflare.steamstatic.com/steam/apps/3240220/header.jpg","linha":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/3240220/a318bd9affe8eee32984b18794b273c256e9b2d6/capsule_231x87.jpg"}'::jsonb, false, null, '{}'::text[], '{}'::text[], null),
  (7, 'the-elder-scrolls-v-skyrim', 'jogo', 'jogos', 'The Elder Scrolls V: Skyrim', 'The Elder Scrolls V: Skyrim é um RPG de ação em mundo aberto, onde você explora a província de Skyrim. Personalize seu personagem, complete missões, enfrente dragões e mergulhe em uma rica história cheia de magia, intriga e aventura.', 'ativo', 149, 59.6, true, null, 489830, array['PS5', 'PS4', 'PS3', 'Xbox Series X/S', 'Xbox 360']::text[], array['RPG', 'Mundo Aberto', 'Fantasia']::text[], 'Bethesda Game Studios', 2011, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/489830/77128/20c56f14e492b05846f7262a246b4e4f0d455f7f/1750536877/hls_264_master.m3u8?t=1476991615","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256672927/movie.293x165.jpg"}'::jsonb, array['ss_73c1a0bb7e1720c8a1847186c3ddd837d3ca7a8d', 'ss_d64b646612ab1402bdda8e400672aa0dbcb352ea', 'ss_b6bb6f79278505b3f48567f08c21f7a0eb171c68', 'ss_921ccea650df936a0b14ebd5dd4ecc73c1d2a12d', 'ss_8c7ecd394afb581b9b2137a3de04433f78fdf4ea', 'ss_50c3da9e29e9b0368889379cdd03a71aba8d614c']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/489830/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (8, 'assassin-s-creed-valhalla', 'jogo', 'jogos', 'Assassin''s Creed Valhalla', 'Assassin''s Creed Valhalla é um jogo de ação e aventura em mundo aberto ambientado na era dos vikings. Você joga como Eivor, um guerreiro viking, enquanto explora a Inglaterra do século IX, participa de batalhas épicas, constrói assentamentos e descobre segredos históricos.', 'ativo', 249.99, 62.5, true, null, 2208920, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['Ação', 'RPG', 'Mundo Aberto']::text[], 'Ubisoft Montreal', 2020, 'midia_fisica', 8, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/2208920/515678/08b6d5b1267d155673daea051094ee1046ddfff7/1750809553/hls_264_master.m3u8?t=1693577111","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256917310/movie.293x165.jpg"}'::jsonb, array['ss_103481084a59b34837113daf27c04679caf743f3', 'ss_e7310b36689ec722d2ea4643efc15bd8fa720c67', 'ss_c3bff917ead50268eb7708ef3bf30e07b58929e9', 'ss_5e527e1e063ef041ca6680f503081274dcc5513a', 'ss_83a5e49815eed62911f27240390c6735b898c13e']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/2208920', null, false, null, '{}'::text[], '{}'::text[], null),
  (9, 'marvel-s-spider-man-miles-morales', 'jogo', 'jogos', 'Marvel''s Spider-Man: Miles Morales', 'Spider-Man: Miles Morales é um jogo de ação e aventura em mundo aberto, onde você assume o papel de Miles Morales, o novo Homem-Aranha. Explore a cidade de Nova York, use habilidades únicas de combate e acrobacias para enfrentar vilões e proteger a cidade.', 'ativo', 249.9, 149.94, true, null, 1817190, array['PS5', 'PS4']::text[], array['Ação', 'Aventura', 'Super-herói', 'Mundo Aberto']::text[], 'Insomniac Games', 2020, 'midia_fisica', 8.5, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1817190/511939/23b99be061a4364c4054df50305d33bf4fecefca/1750737986/hls_264_master.m3u8?t=1672784160","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256915121/movie.293x165.jpg"}'::jsonb, array['ss_a240e0c6f37569493ed749d9317718d8ce9f5d18', 'ss_02bb2ac97c3ce854344a537d9ed89c70ba45c3d3', 'ss_616a0e2ab905281a483d99d0e1f07fc0749770d2', 'ss_1950c472438a5ccde0f9e7c112dceaddd7cd52f1', 'ss_4198c024c13b1477240cf043cd4f7867913f77e1', 'ss_971beba92204ad268878b23aa5288cc4f2118788']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/1817190', null, false, null, '{}'::text[], '{}'::text[], null),
  (11, 'death-stranding-director-s-cut', 'jogo', 'jogos', 'Death Stranding Director''s Cut', 'Death Stranding é um jogo de ação e aventura em mundo aberto, onde você joga como Sam Porter Bridges, um entregador em um mundo pós-apocalíptico. Explore paisagens desoladas, conecte comunidades isoladas e enfrente criaturas sobrenaturais enquanto desvenda os mistérios do mundo.', 'ativo', 199.9, 99.95, true, null, 1850570, array['PS5']::text[], array['Ação', 'Aventura', 'Ficção Científica']::text[], 'Kojima Productions', 2022, 'midia_fisica', 8.5, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1850570/448933/909ae17650e060d3f7853d6891a7936fb67026e1/1750738559/hls_264_master.m3u8?t=1683196663","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256878920/movie.293x165.jpg"}'::jsonb, array['ss_f64a1140651ff5af30eb63bb6e5b41753d00a98e', 'ss_4b6d7d010d1701b2b57bf8ef1b4975a04b3d632f', 'ss_bc8812817c074772822c1d1e8a6b016983cf05e8', 'ss_d47bde2e349606b3ef1f641e2d8fb7ccf1adba77', 'ss_8f0a2b1f6ea6da05c53f802034e08cbe92aaccab', 'ss_73eb002b5070299aae3727bd07ce6d51e4a82b10']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1850570/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (12, 'subnautica', 'jogo', 'jogos', 'Subnautica', 'Subnautica é um jogo de ação e aventura em mundo aberto, onde você explora um planeta oceânico alienígena. Sobreviva em um ambiente subaquático, construa bases, colete recursos e descubra a história por trás do planeta enquanto enfrenta criaturas marinhas perigosas.', 'ativo', 79.99, null, false, null, 264710, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['Sobrevivência', 'Aventura', 'Mundo Aberto']::text[], 'Unknown Worlds', 2018, 'midia_fisica', 8.7, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/264710/143519/33594902d34e588ce90d9905c30aa902198fea59/1750490623/hls_264_master.m3u8?t=1516828564","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256706800/movie.293x165.jpg"}'::jsonb, array['ss_e182b6b20bb797500f9f63c561586d920d44e37c', 'ss_970a13f246e33e0df26d93baf9f8e975732adb4b', 'ss_5f2f2ea498cdc632cbffd6cf37c1a09670eb3272', 'ss_cebc378d2f7bc78978c21db4e3c5e12ccd067349', 'ss_0ace7f8b4350b8fbdd16345a76bc30545256e918', 'ss_f0eeabe108c2bc2b3e370b9828fb280035b50db2']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/264710', null, false, null, '{}'::text[], '{}'::text[], null),
  (14, 'dark-souls-iii', 'jogo', 'jogos', 'Dark Souls III', 'Dark Souls III é um RPG de ação em mundo aberto, conhecido por sua dificuldade desafiadora e combate estratégico. Explore um mundo sombrio e interconectado, enfrente inimigos formidáveis e descubra segredos enquanto busca a verdade por trás da maldição que assola o reino.', 'ativo', 199.9, null, false, null, 374320, array['PS4']::text[], array['RPG', 'Ação', 'Soulslike', 'Fantasia']::text[], 'FromSoftware', 2016, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/374320/56808/0af7e6e54ad977d6c9a83cbe2d4fe5a763a70f02/1750520236/hls_264_master.m3u8?t=1700587302","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256663134/movie.293x165.jpg"}'::jsonb, array['ss_5efd318b85a3917d1c6e717f4cb813b47547cd6f', 'ss_1c0fa39091901496d77cf4cecfea4ffb056d6452', 'ss_1318a04ef11d87f38aebe6d47a96124f8f888ca8', 'ss_61524dee9ebf72d462638f21adbbbea4c93d791d', 'ss_fe1dc6761a9004aa39c2e6e62181593b7263edf9', 'ss_27397db724cfd5648655c1056ff5d184147a4c50']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/374320/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (15, 'sekiro-shadows-die-twice', 'jogo', 'jogos', 'Sekiro: Shadows Die Twice', 'Sekiro: Shadows Die Twice é um jogo de ação e aventura em mundo aberto, ambientado no Japão feudal. Você joga como um shinobi chamado Sekiro, em uma missão para resgatar seu mestre e enfrentar inimigos formidáveis. O jogo é conhecido por seu combate desafiador e mecânicas de furtividade.', 'ativo', 249.9, 124.95, true, null, 814380, array['PS4']::text[], array['Ação', 'Aventura', 'Soulslike']::text[], 'FromSoftware', 2019, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/814380/322401/63cf1fdf9c16536f04b08a5b1939909f7a99a340/1750586450/hls_264_master.m3u8?t=1603837979","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256806899/movie.293x165.jpg"}'::jsonb, array['ss_0f7b0f8ed9ffc49aba26f9328caa9a1d59ad60f0', 'ss_2685dd844a2a523b6c7ec207d46a538db6a908cd', 'ss_15f0e9982621aed44900215ad283811af0779b1d', 'ss_1e6f5540866a5564d65df915c22fe1e57e336a6f', 'ss_3d6b38c382c0eafb02dc90d22f33fd292e4e5cf3']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/814380/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (16, 'resident-evil-village', 'jogo', 'jogos', 'Resident Evil Village', 'Resident Evil Village é um jogo de ação e aventura em mundo aberto, ambientado em uma vila misteriosa. Você joga como Ethan Winters, enquanto enfrenta criaturas aterrorizantes e desvenda os segredos sombrios da vila. O jogo combina elementos de terror, exploração e combate intenso.', 'ativo', 169, null, false, null, 1196590, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['Terror', 'Ação', 'Sobrevivência']::text[], 'Capcom', 2021, 'midia_fisica', 8.4, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1196590/353097/ab42831befc22df81eaefe3d5e9fc239f335dfc3/1750637462/hls_264_master.m3u8?t=1615523888","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256825274/movie.293x165.jpg"}'::jsonb, array['ss_d25704b01be292d1337df4fea0fba2aab322b58a', 'ss_8113ec993ec474055c4cdce5ee86f91f7cf6663f', 'ss_50283e6df9d2f3f24ff4a1a36a94ae307e21cee8', 'ss_363d9c05ee0a974b766938610a3352e7a89b9c92', 'ss_e2bdaa9a0eeae714b3ad3ba49c9ae83a3930f08e', 'ss_d296efbc9a5d87bf20b2ea19134f35ba203ae813']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1196590/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (17, 'far-cry-5', 'jogo', 'jogos', 'Far Cry 5', 'Far Cry 5 é um jogo de ação e aventura em mundo aberto, ambientado em Hope County, Montana. Você joga como um xerife local, enquanto enfrenta uma seita religiosa perigosa. Explore vastas paisagens, participe de missões emocionantes e enfrente inimigos em combates intensos.', 'ativo', 99.99, 15, true, null, 552520, array['PS4']::text[], array['Tiro', 'Ação', 'Mundo Aberto']::text[], 'Ubisoft Montreal', 2018, 'midia_fisica', 8, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/552520/155757/a70cd60188b0d1d8fd08e97180061674b512c51d/1750549438/hls_264_master.m3u8?t=1522436975","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256712971/movie.293x165.jpg"}'::jsonb, array['8c2c63dfb8711e3bdaaeb2400668f690f24ab5b3/ss_8c2c63dfb8711e3bdaaeb2400668f690f24ab5b3', '93e1fad73390e7d7a73ab886300e7c26717a5c00/ss_93e1fad73390e7d7a73ab886300e7c26717a5c00', '7a3b7b4d6e56aa71b59367e4467cfc49715b6914/ss_7a3b7b4d6e56aa71b59367e4467cfc49715b6914', 'c4a1822091beb6c0e8e18687e9d4f676878c1ffe/ss_c4a1822091beb6c0e8e18687e9d4f676878c1ffe', 'af9896dcb2d21cc5fde7b708e29aa67a454ce260/ss_af9896dcb2d21cc5fde7b708e29aa67a454ce260', '651703215a2116d2cc7e5ef9491670cbde0cf7d4/ss_651703215a2116d2cc7e5ef9491670cbde0cf7d4']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/552520/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (18, 'dying-light', 'jogo', 'jogos', 'Dying Light', 'Dying Light é um jogo de ação e aventura em mundo aberto, ambientado em uma cidade infestada por zumbis. Você joga como um sobrevivente, enquanto explora a cidade, coleta recursos e enfrenta hordas de mortos-vivos. O jogo combina parkour, combate intenso e elementos de sobrevivência.', 'ativo', 89.99, 27, true, null, 239140, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['Sobrevivência', 'Terror', 'Mundo Aberto', 'Ação']::text[], 'Techland', 2015, 'midia_fisica', 8, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/239140/698096/dd7e6951d39ca12b2704b24e370e01e2efec03cf/1750483635/hls_264_master.m3u8?t=1715275593","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257022021/movie.293x165.jpg"}'::jsonb, array['ss_a3771358b8eb4ea4c8f99c5850711f55b87804de', 'ss_1f0dc94f46fa1a953827188188887f6a12911ec2', 'ss_488226f013287012e0feaed2fb7799dbe038fd00', 'ss_37f8192f3bf85359ddee0b5c2e9a58eaaf6c4026', 'ss_ac414827362042b5f4a95ab90df508adc822ddc1', 'ss_3b41c96ae1a6f31c597187672221b8db9b78419b']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/239140/c02d95e3f9bd0f3dae3f3f7800f36c42f1bca348/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (21, 'dark-souls-ii-scholar-of-the-first-sin', 'jogo', 'jogos', 'Dark Souls II: Scholar of the First Sin', 'Dark Souls II é um RPG de ação em mundo aberto, conhecido por sua dificuldade desafiadora e combate estratégico. Explore um mundo sombrio e interconectado, enfrente inimigos formidáveis e descubra segredos enquanto busca a verdade por trás da maldição que assola o reino.', 'ativo', 129.9, null, false, null, 335300, array['PS4', 'PS3', 'Xbox 360']::text[], array['RPG', 'Ação', 'Soulslike', 'Fantasia']::text[], 'FromSoftware', 2015, 'midia_fisica', 8.7, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/335300/33754/947c35553d4af308d4ce5d11ae49a8d6704b765c/1750510552/hls_264_master.m3u8?t=1447372195","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2038280/movie.293x165.jpg"}'::jsonb, array['ss_589f08dc4d8580785923c89749101a15014bcdf9', 'ss_724c043f3005c09c71e683e4d4b633711d7ccd49', 'ss_a6af51265aac7894c2f233f67089715899d9fe7c', 'ss_b9e5f5afb7358b242d4a669cf6f622de55edf1a0', 'ss_fe75766ecb5828879ce1ee74b0ff345343ec33b2', 'ss_1fc27c02801d97cce73912de09ecd7d823ac80cf']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/335300', null, false, null, '{}'::text[], '{}'::text[], null),
  (22, 'cuphead', 'jogo', 'jogos', 'Cuphead', 'Cuphead é um jogo de ação e aventura em mundo aberto, conhecido por seu estilo visual inspirado em desenhos animados dos anos 1930. Você joga como Cuphead, enfrentando chefes desafiadores em batalhas intensas. O jogo combina plataformas, tiro e elementos de RPG, oferecendo uma experiência única e desafiadora.', 'ativo', 36.99, null, false, null, 268910, array['PS4']::text[], array['Ação', 'Plataforma', 'Indie']::text[], 'Studio MDHR', 2017, 'midia_fisica', 8.8, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/268910/476013/2be829e20a796ed2e0e707fb1c747e1d15f6fb25/1750499396/hls_264_master.m3u8?t=1656595223","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256894191/movie.293x165.jpg"}'::jsonb, array['ss_e3096a5555cb77d88db165c83d5ef3a24af1354a', 'ss_615455299355eaf552c638c7ea5b24a8b46e02dd', 'ss_483fb089be0093beeef03525276803a9ca4f66a1', 'ss_48477e4a865827aa0be6a44f00944d8d2a3e5eb9', 'ss_380296effbf1073bbedfd480e50cf246eb542b66', 'ss_aefad3850c3bc04000cbe0d620bea6807e0a0331']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/268910/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (23, 'dark-souls-remastered', 'jogo', 'jogos', 'Dark Souls Remastered', 'Dark Souls Remastered é uma versão aprimorada do aclamado RPG de ação em mundo aberto. Explore um mundo sombrio e interconectado, enfrente inimigos formidáveis e descubra segredos enquanto busca a verdade por trás da maldição que assola o reino. Com gráficos melhorados e jogabilidade refinada, esta versão oferece uma experiência ainda mais imersiva.', 'ativo', 159.9, null, false, null, 570940, array['PS4']::text[], array['RPG', 'Ação', 'Soulslike', 'Fantasia']::text[], 'FromSoftware', 2018, 'midia_fisica', 8.5, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/570940/164454/5553fe8364a89c3437a7c6b03a36cf3acae2cb61/1750551881/hls_264_master.m3u8?t=1605604943","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256717685/movie.293x165.jpg"}'::jsonb, array['ss_3a71463e4ccaf28c5c27f6cf8d32a3a125f45404', 'ss_92b2ba470cbfdb8839b649b3f478e5531dd81a17', 'ss_626cc310dc9ac7fb146011582c864a35e5f3e381', 'ss_f1617a419eb3b0cd877ec71230c59aa2672b62dc', 'ss_f60f54e58b13d0744853672ccd35810397e3fa26', 'ss_b4a80bd6e828a81db09ecbef5694e5d0cddb2caf']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/570940/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (25, 'elden-ring', 'jogo', 'jogos', 'Elden Ring', 'Elden Ring é um RPG de ação em mundo aberto, desenvolvido pela FromSoftware. Explore um vasto mundo repleto de segredos, monstros e desafios. Com uma narrativa envolvente e combate estratégico, Elden Ring oferece uma experiência épica para os fãs de jogos desafiadores e imersivos.', 'ativo', 229.9, null, false, null, 1245620, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['RPG', 'Soulslike', 'Mundo Aberto', 'Fantasia']::text[], 'FromSoftware', 2022, 'midia_fisica', 9.6, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1245620/468149/7d588828f80907ca97efdcb1e6ef72b4ce2b1d0d/1750650511/hls_264_master.m3u8?t=1654109241","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256889456/movie.293x165.jpg"}'::jsonb, array['ss_943bf6fe62352757d9070c1d33e50b92fe8539f1', 'ss_dcdac9e4b26ac0ee5248bfd2967d764fd00cdb42', 'ss_3c41384a24d86dddd58a8f61db77f9dc0bfda8b5', 'ss_e0316c76f8197405c1312d072b84331dd735d60b', 'ss_ef61b771ee6b269b1f0cb484233e07a0bfb5f81b', 'ss_b1b91299d7e4b94201ac840aa64de54d9f5cb7f3']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1245620/page_bg_raw.jpg', null, true, null, '{}'::text[], '{}'::text[], null),
  (26, 'hollow-knight', 'jogo', 'jogos', 'Hollow Knight', 'Hollow Knight é um jogo de ação e aventura em mundo aberto, ambientado em um reino subterrâneo chamado Hallownest. Explore cavernas, enfrente inimigos desafiadores e descubra segredos enquanto desvenda a história do reino. Com uma atmosfera sombria e uma jogabilidade precisa, Hollow Knight oferece uma experiência envolvente para os fãs de jogos de plataforma e exploração.', 'ativo', 46.99, 23.5, true, null, 367520, array['PS4']::text[], array['Metroidvania', 'Plataforma', 'Indie']::text[], 'Team Cherry', 2017, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/367520/89922/b71b6a50e9aa2334fddca8fa2197cb26a3640832/1750517691/hls_264_master.m3u8?t=1497589417","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256679401/movie.293x165.jpg"}'::jsonb, array['ss_5384f9f8b96a0b9934b2bc35a4058376211636d2', 'ss_d5b6edd94e77ba6db31c44d8a3c09d807ab27751', 'ss_a81e4231cc8d55f58b51a4a938898af46503cae5', 'ss_62e10cf506d461e11e050457b08aa0e2a1c078d0', 'ss_bd76bd88bc5334ee56ae3d5f0d8dec4455e8e3b8', 'ss_33a645903d6dd9beec39f272a3daf57174a6cc26']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/367520', null, false, null, '{}'::text[], '{}'::text[], null),
  (27, 'batman-arkham-asylum-goty', 'jogo', 'jogos', 'Batman: Arkham Asylum GOTY', 'Batman: Arkham Asylum é um jogo de ação e aventura em mundo aberto, onde você assume o papel do Cavaleiro das Trevas. Explore o asilo Arkham, enfrente vilões icônicos e utilize gadgets para combater o crime nesta emocionante história.', 'ativo', 28.99, 7.25, true, null, 35140, array['PS3', 'Xbox 360']::text[], array['Ação', 'Aventura', 'Super-herói']::text[], 'Rocksteady Studios', 2009, 'midia_fisica', 9.1, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/35140/3400/00c700e321bc8ae62d16985ff36761b4e5553dd7/1750485156/hls_264_master.m3u8?t=1457569846","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/5642/movie.293x165.jpg"}'::jsonb, array['ss_7c61451755b28ffd5254a22aa9a43003d9896b89', 'ss_312e1fccf930e7aad2a531727c4280f05a22c73c', 'ss_ff136f39374639b8e407724be1566fbfb9506113', 'ss_5e7c44cb994f2de4acdddd558441b172188d6034', 'ss_b6517e8c29c03a8348fe9eccc63e039e0478cd02', 'ss_3c960e9830529fef675bd1c6811ca0a9cd26d012']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/35140', null, false, null, '{}'::text[], '{}'::text[], null),
