  (30, 'subnautica-below-zero', 'jogo', 'jogos', 'Subnautica: Below Zero', 'Subnautica: Below Zero é um jogo de ação e aventura em mundo aberto, ambientado em um planeta oceânico alienígena. Explore ambientes subaquáticos congelados, colete recursos e descubra a história por trás do planeta enquanto enfrenta criaturas perigosas.', 'ativo', 89.99, null, false, null, 848450, array['PS5', 'PS4', 'Xbox Series X/S']::text[], array['Sobrevivência', 'Aventura', 'Mundo Aberto']::text[], 'Unknown Worlds', 2021, 'midia_fisica', 8.2, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/848450/361258/82151770fcaf7d6667a364a76c0f16b836513514/1750588821/hls_264_master.m3u8?t=1618322274","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/256830049/movie.293x165.jpg"}'::jsonb, array['ss_5011daad83f8494eda0826e4bbc91181239ad5d7', 'ss_69bdcf6ce29ba61650f0b2551a3494af67be09ac', 'ss_3c3403337b972d4913e3a6b4f34e0f47e484c042', 'ss_5bc21362aa200d08fe25203cbe50debedd8f11a3', 'ss_9e3d6ab0db5442f7bcbeb923da47d3a80023f50f', 'ss_e5c0f0272552f4aff9129ce3683131bdabd5983c']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/848450/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
