  (65, 'ghost-of-tsushima-director-s-cut', 'jogo', 'jogos', 'Ghost of Tsushima Director''s Cut', 'Uma tempestade se aproxima. Vivencie a experiência completa de Ghost of Tsushima Versão do Diretor no PC e forje seu próprio caminho neste jogo de ação e aventura de mundo aberto para descobrir suas maravilhosas surpresas. Trazido pela Sucker Punch Productions, Nixxes Software e PlayStation Studios.', 'ativo', 249.9, null, false, null, 2215430, array['PS5', 'PS4']::text[], array['Ação', 'Mundo Aberto', 'Samurai']::text[], 'Sucker Punch Productions', 2024, 'midia_fisica', 9.3, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/2215430/698159/0782dd4de4cf6d46533d828cc9f8cb3c19ec5556/1750809558/hls_264_master.m3u8?t=1715871580","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257022058/movie.293x165.jpg"}'::jsonb, array['ss_51eb1a47a41271abb0aa781de576f704d95b601b', 'ss_d60e16422fc1605181e0fedee3e2cfc1e02c750e', 'ss_11409331d57966ef193d66ffcded569d02a4e034', 'ss_bd593bab36968778b95ed4a1a12ec82d2350d351', 'ss_63cc7ea967bf808c73129792d9ae8e3fdb2962bf', 'ss_b94e296457324be29466facc1fd93a91b6189a9b']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/2215430', null, true, null, '{}'::text[], '{}'::text[], null),
