  (114, 'prince-of-persia-the-sands-of-time', 'jogo', 'jogos', 'Prince of Persia: The Sands of Time', 'Nas areias escaldantes da antiga Pérsia, existe uma lenda contada em um idioma antigo. Ela fala sobre um tempo de sangue e governado pela falsidade. Através dos poderes das trevas de uma adaga mágica, um jovem príncipe é levado a libertar um mal mortal sobre um belo reino.', 'ativo', 29.99, null, false, null, 13600, array['PS3', 'PS2']::text[], array['Ação', 'Aventura', 'Plataforma']::text[], 'Kudosoft', 2003, 'midia_fisica', 9, null, array['0000003878', '0000003879', '0000003880', '0000003881', '0000003940', '0000003941']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/13600', '{"capa":"https://cdn.cloudflare.steamstatic.com/steam/apps/13600/header.jpg","capaPequena":"https://cdn.cloudflare.steamstatic.com/steam/apps/13600/header.jpg","destaque":"https://cdn.cloudflare.steamstatic.com/steam/apps/13600/header.jpg","linha":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/13600/capsule_231x87.jpg"}'::jsonb, false, null, '{}'::text[], '{}'::text[], null),
