  (116, 'bully-scholarship-edition', 'jogo', 'jogos', 'Bully: Scholarship Edition', 'Bully conta a história de Jimmy Hopkins, um adolescente de 15 anos que passa pela hilaridade e estranheza da adolescência. Vença os esportistas na queimada, sacaneie as patricinhas, salve os nerds, beije a garota e, por fim, explore a hierarquia social da pior escola da região.', 'ativo', 39.99, null, false, null, 12200, array['PS4', 'PS2', 'Xbox 360']::text[], array['Ação', 'Mundo Aberto', 'Aventura']::text[], 'Rockstar New England', 2006, 'midia_fisica', 8.7, null, array['0000006051', '0000006052', '0000006066', '0000006055', '0000006056', '0000006067']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/12200', null, false, null, '{}'::text[], '{}'::text[], null),
