  (121, 'fallout-new-vegas', 'jogo', 'jogos', 'Fallout: New Vegas', 'Um mensageiro é baleado e deixado para morrer no deserto de Mojave. Sobreviva, escolha seus aliados entre as facções que disputam New Vegas e decida o destino da cidade num RPG pós-apocalíptico cheio de escolhas e consequências.', 'ativo', 39, 9.75, true, null, 22380, array['PS3', 'Xbox 360']::text[], array['RPG', 'Mundo Aberto', 'Pós-apocalíptico']::text[], 'Obsidian Entertainment', 2010, 'midia_fisica', 9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/22380/1201167942/4f0d3268fde83e09d4b80e152ab16b30236ce547/1761162024/hls_264_master.m3u8?t=1761163002","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257221243/dc315a6da1c8b69b254344c0c92379161e1b9888/movie_600x337.jpg"}'::jsonb, array['ss_62f8d0b006935ff6de7fe276f713e7d15e579bc9', 'ss_ec8a28942fcb5cb15718f949ab81124932a5084d', 'ss_f703adcb9aa1d718a39288adf7d2e1b4dc0e568a', 'ss_e05e3697347c076d3382188bcf883339cf6144d5', 'ss_e430a2c8a841d4bc32bd8207223a91e3dbe0cdea', 'ss_7cf86a5e4c98db502ca36444d883f94c4147f5d2']::text[], 'https://store.akamai.steamstatic.com/images/storepagebackground/app/22380', null, false, null, '{}'::text[], '{}'::text[], null),
