  (135, 'hi-fi-rush', 'jogo', 'jogos', 'Hi-Fi Rush', 'Sinta a batida enquanto o aspirante a estrela Chai e seu inesperado time de aliados lutam contra uma megacorporação maligna usando um estrondoso combate ritmado! Da Tango Gameworks, chega agora Hi-Fi RUSH, um novo jogo de ação em que o mundo entra em sincronia com a música!', 'ativo', 109, null, false, null, 1817230, array['PS5', 'Xbox Series X/S']::text[], array['Ação', 'Hack and Slash']::text[], 'Tango Gameworks', 2023, 'midia_fisica', 8.9, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/1817230/1666817001/b4923fadd44dd5642228e85bc522ac6f739a781e/1762755913/hls_264_master.m3u8?t=1763072078","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257228999/6f17ed80a4a0505208b6e3ef68a20be024718416/movie_600x337.jpg"}'::jsonb, array['ss_382e9d5abb00498eee6a86b0366a2db7826268b7', 'ss_8a13650ffe930da77593dae80f0118588c46a5ca', 'ss_62a7ff68fff7850be6a0784eff41edafd33b2099', 'ss_7dfaee4616fbed65b2b0fcb82d55dc0a957fd8a5', 'ss_3e17ba9ca8dd57d0911881995e5a3e2ab7dd31f1']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/1817230/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (136, 'indiana-jones-e-o-grande-circulo', 'jogo', 'jogos', 'Indiana Jones e o Grande Círculo', 'Descubra um dos maiores mistérios da história em uma aventura solo em primeira pessoa. Em 1937, forças sinistras estão vasculhando o mundo atrás do segredo de um poder ancestral ligado ao Grande Círculo. Só uma pessoa pode impedi-las: Indiana Jones™.', 'ativo', 349, null, false, null, 2677660, array['PS5', 'Xbox Series X/S']::text[], array['Ação', 'Aventura']::text[], 'MachineGames', 2024, 'midia_fisica', 8.7, '{"hls":"https://video.akamai.steamstatic.com/store_trailers/2677660/793962/61d662de943f7a2c5dd2b846aed7275ae4f241bb/1750818472/hls_264_master.m3u8?t=1749403440","capa":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/257078301/3f57ed9adc070e6e74898cafd4ef1676bdccc53b/movie_600x337.jpg"}'::jsonb, array['ss_8221cf729bc6491919a8532679be64f1c67dcdaf', 'ss_ef822ff1dca1f8badda449656bc4c969b60a784f', 'ss_993951f7591595daa6e121d8f5aa77d61080efbd', 'ss_e95faa8f895e21296c5dcb35842e5480657148bc', 'ss_499e0d79f86e532e40c1b93f9442cb52653a5d15', 'ss_ad5ca5a90a2c5cd70f62e6b8d286b794b33c38d5']::text[], 'https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2677660/page_bg_raw.jpg', null, false, null, '{}'::text[], '{}'::text[], null),
  (5001, 'mouse-gamer-sem-fio-26k-dpi', 'acessorio', 'pc', 'Mouse gamer sem fio 26K DPI', 'Leve, rápido e preciso: o sensor de 26.000 DPI acompanha cada movimento sem atraso, e a conexão sem fio de 1 ms responde como um mouse com cabo. Os 63 g e o formato simétrico deixam o mouse confortável em partidas longas.', 'ativo', 349.9, 297.41, true, 'mouse', null, '{}'::text[], '{}'::text[], null, null, null, 9.1, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'Mac']::text[], array['Sensor óptico de 26.000 DPI', 'Conexão 2,4 GHz e Bluetooth', 'Bateria de até 90 horas', 'Peso de 63 g', '6 botões programáveis']::text[], 1284),
  (5002, 'teclado-mecanico-75-hot-swap-rgb', 'acessorio', 'pc', 'Teclado mecânico 75% hot-swap RGB', 'Compacto sem abrir mão das setas e das teclas de função. Os switches lineares já vêm lubrificados de fábrica para um toque suave e silencioso, e o hot-swap permite trocar cada switch sem ferramenta.', 'ativo', 499.9, 449.91, true, 'teclado', null, '{}'::text[], '{}'::text[], null, null, null, 9, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'Mac']::text[], array['Layout 75% (ABNT2)', 'Switches lineares lubrificados', 'Troca de switches sem solda (hot-swap)', 'Iluminação RGB por tecla', 'Cabo USB-C removível']::text[], 864),
  (5003, 'headset-gamer-7-1-sem-fio', 'acessorio', 'pc', 'Headset gamer 7.1 sem fio', 'Ouça de onde vêm os passos antes de ver o inimigo. O surround 7.1 e os drivers de 50 mm entregam graves fortes sem embolar os detalhes, e o microfone com redução de ruído deixa sua voz limpa no chat.', 'ativo', 599.9, 479.92, true, 'headset', null, '{}'::text[], '{}'::text[], null, null, null, 8.8, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'PS5', 'Switch']::text[], array['Som surround 7.1 virtual', 'Drivers de 50 mm', 'Microfone removível com redução de ruído', 'Bateria de até 30 horas', 'Almofadas em espuma de memória']::text[], 2031),
  (5004, 'mousepad-xl-speed-90-x-40-cm', 'acessorio', 'pc', 'Mousepad XL speed 90 x 40 cm', 'Espaço para o mouse e para o teclado em uma superfície só. O tecido speed deixa o mouse deslizar rápido e por igual, e a base de borracha mantém tudo no lugar.', 'ativo', 129.9, null, false, 'mousepad', null, '{}'::text[], '{}'::text[], null, null, null, 9.3, null, '{}'::text[], null, null, false, 'Universal Gear', array['Todos os mouses']::text[], array['Tamanho 90 x 40 cm', 'Superfície speed de tecido', 'Base de borracha antiderrapante', 'Bordas costuradas', '4 mm de espessura']::text[], 3420),
  (5005, 'webcam-full-hd-60-fps', 'acessorio', 'streaming', 'Webcam Full HD 60 fps', 'Imagem fluida em 60 fps para lives e chamadas, com foco automático e correção de luz que deixam você nítido mesmo em quartos escuros.', 'ativo', 389.9, 343.11, true, 'webcam', null, '{}'::text[], '{}'::text[], null, null, null, 8.6, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'Mac']::text[], array['1080p a 60 fps', 'Foco automático', 'Dois microfones estéreo', 'Correção de luz automática', 'Tampa de privacidade']::text[], 742),
  (5006, 'microfone-condensador-usb', 'acessorio', 'streaming', 'Microfone condensador USB', 'Voz clara e encorpada para streams, podcasts e partidas em grupo. O padrão cardioide capta você e ignora o barulho em volta, e basta ligar no USB para usar.', 'ativo', 459.9, null, false, 'microfone', null, '{}'::text[], '{}'::text[], null, null, null, 8.9, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'Mac', 'PS5']::text[], array['Cápsula condensadora cardioide', '24 bits / 96 kHz', 'Botão de mudo com luz', 'Saída para fone com ajuste de volume', 'Suporte de mesa incluso']::text[], 615),
  (5007, 'monitor-gamer-27-qhd-165-hz', 'acessorio', 'pc', 'Monitor gamer 27" QHD 165 Hz', 'Resolução QHD com 165 Hz para jogos competitivos sem borrão de movimento. O painel IPS mantém as cores fiéis de qualquer ângulo.', 'ativo', 1899.9, 1557.92, true, 'monitor', null, '{}'::text[], '{}'::text[], null, null, null, 9.2, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'PS5', 'Xbox Series X/S']::text[], array['Painel IPS de 27" 2560 x 1440', '165 Hz e 1 ms', 'HDR10', 'Compatível com FreeSync e G-Sync', 'HDMI 2.0 e DisplayPort 1.4']::text[], 958),
  (5008, 'ssd-nvme-1-tb-pcie-4-0', 'acessorio', 'pc', 'SSD NVMe 1 TB PCIe 4.0', 'Jogos carregando em segundos. Com até 7.000 MB/s de leitura, este SSD acaba com as telas de carregamento e funciona também na expansão de armazenamento do PS5.', 'ativo', 549.9, 412.43, true, 'ssd', null, '{}'::text[], '{}'::text[], null, null, null, 9.4, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'PS5']::text[], array['1 TB de armazenamento', 'Leitura de até 7.000 MB/s', 'Formato M.2 2280', 'Compatível com a expansão do PS5', 'Garantia de 5 anos']::text[], 1876),
  (5009, 'controle-sem-fio-pro', 'acessorio', 'videogames', 'Controle sem fio Pro', 'Analógicos com sensor Hall que não sofrem desgaste nem drift com o tempo, botões traseiros para mapear comandos e conexão com PC, Switch e celular.', 'ativo', 399.9, 359.91, true, 'controle', null, '{}'::text[], '{}'::text[], null, null, null, 8.9, null, '{}'::text[], null, null, false, 'Universal Gear', array['PC', 'Switch', 'Android', 'iOS']::text[], array['Analógicos com sensor Hall (sem drift)', 'Gatilhos analógicos', '2 botões traseiros programáveis', 'Vibração dupla', 'Bateria de até 20 horas']::text[], 2245),
  (5010, 'base-carregadora-dupla-para-controles', 'acessorio', 'videogames', 'Base carregadora dupla para controles', 'Encaixe os dois controles e eles estão prontos para a próxima sessão. Sem cabos espalhados pela mesa.', 'ativo', 179.9, null, false, 'base', null, '{}'::text[], '{}'::text[], null, null, null, 8.7, null, '{}'::text[], null, null, false, 'Universal Gear', array['PS5']::text[], array['Carrega dois controles ao mesmo tempo', 'Carga completa em cerca de 3 horas', 'Luz indicadora de carga', 'Encaixe sem cabo', 'Fonte inclusa']::text[], 1102),
  (5011, 'controle-telescopico-para-celular', 'acessorio', 'celular', 'Controle telescópico para celular', 'Transforma o celular em um console portátil. A conexão por USB-C não tem atraso nem precisa de bateria, e funciona com jogos nativos e na nuvem.', 'ativo', 329.9, 280.41, true, 'controle-celular', null, '{}'::text[], '{}'::text[], null, null, null, 8.8, null, '{}'::text[], null, null, false, 'Universal Gear', array['Android', 'iOS']::text[], array['Encaixa celulares de até 7"', 'Conexão USB-C sem atraso', 'Analógicos com sensor Hall', 'Entrada para carregar enquanto joga', 'Funciona com jogos na nuvem']::text[], 934),
  (5012, 'fone-tws-gamer-de-baixa-latencia', 'acessorio', 'audio', 'Fone TWS gamer de baixa latência', 'Fones sem fio com modo jogo de 45 ms: o som chega junto com a imagem. O cancelamento de ruído ajuda a focar mesmo no ônibus.', 'ativo', 279.9, 223.92, true, 'fone', null, '{}'::text[], '{}'::text[], null, null, null, 8.5, null, '{}'::text[], null, null, false, 'Universal Gear', array['Android', 'iOS', 'PC', 'Switch']::text[], array['Modo jogo com 45 ms de latência', 'Bluetooth 5.3', 'Cancelamento de ruído ativo', 'Até 32 horas com o estojo', 'Resistente a suor (IPX4)']::text[], 1563),
  (5013, 'carregador-gan-65-w-usb-c', 'acessorio', 'celular', 'Carregador GaN 65 W USB-C', 'Um carregador só para o celular, o Switch e o notebook. A tecnologia GaN deixa o carregador pequeno e esquentando menos.', 'ativo', 189.9, null, false, 'carregador', null, '{}'::text[], '{}'::text[], null, null, null, 9, null, '{}'::text[], null, null, false, 'Universal Gear', array['Android', 'iOS', 'Switch', 'Notebooks USB-C']::text[], array['65 W de potência', 'Tecnologia GaN (compacto e frio)', '2 portas USB-C e 1 USB-A', 'Carga rápida PD 3.0 e QC 4.0', 'Proteção contra superaquecimento']::text[], 2780),
