  (5016, 'ring-light-26-cm-com-tripe', 'acessorio', 'streaming', 'Ring light 26 cm com tripé', 'Iluminação uniforme e sem sombras para lives, vídeos e chamadas. Ajuste a cor e o brilho para combinar com o seu ambiente.', 'ativo', 199.9, 169.92, true, 'ringlight', null, '{}'::text[], '{}'::text[], null, null, null, 8.6, null, '{}'::text[], null, null, false, 'Universal Gear', array['Celular', 'Webcam']::text[], array['Anel de LED de 26 cm', '3 temperaturas de cor', '10 níveis de brilho', 'Tripé ajustável até 1,6 m', 'Suporte para celular']::text[], 1215),
