  (5018, 'smartphone-5g-256-gb-tela-6-7', 'acessorio', 'celulares', 'Smartphone 5G 256 GB tela 6,7"', 'Tela grande e fluida para jogos e vídeos, câmera que acerta de dia e de noite e bateria para o dia inteiro. Com 5G e 256 GB, sobra espaço para fotos, apps e jogos pesados.', 'ativo', 2499.9, 2249.91, true, 'celular', null, '{}'::text[], '{}'::text[], null, null, null, 9, null, '{}'::text[], null, null, false, 'Universal Gear', array['5G', 'Dual chip', 'NFC']::text[], array['Tela AMOLED de 6,7" a 120 Hz', '256 GB de armazenamento e 8 GB de RAM', 'Câmera principal de 50 MP com estabilização', 'Bateria de 5.000 mAh com carga de 45 W', 'Resistente a água e poeira (IP68)']::text[], 2140),
  (5019, 'smartphone-128-gb-dourado', 'acessorio', 'celulares', 'Smartphone 128 GB dourado', 'Acabamento dourado, tela grande e bateria que aguenta o dia todo. Um celular completo para redes sociais, fotos e jogos do dia a dia, com ótimo custo-benefício.', 'ativo', 1499.9, 1424.91, true, 'celular-dourado', null, '{}'::text[], '{}'::text[], null, null, null, 8.6, null, '{}'::text[], null, null, false, 'Universal Gear', array['4G', 'Dual chip']::text[], array['Tela de 6,5" a 90 Hz', '128 GB de armazenamento e 6 GB de RAM', 'Câmera dupla de 48 MP', 'Bateria de 5.000 mAh', 'Leitor de digital na lateral']::text[], 1876),
  (5020, 'tablet-11-128-gb-com-caneta', 'acessorio', 'celulares', 'Tablet 11" 128 GB com caneta', 'Tela grande para estudar, desenhar, assistir e jogar. A caneta inclusa transforma o tablet em caderno, e os quatro alto-falantes deixam filmes e jogos mais imersivos.', 'ativo', 1899.9, 1747.91, true, 'tablet', null, '{}'::text[], '{}'::text[], null, null, null, 8.8, null, '{}'::text[], null, null, false, 'Universal Gear', array['Wi-Fi', 'Bluetooth']::text[], array['Tela de 11" com 2K e 90 Hz', '128 GB, expansível com cartão', 'Caneta inclusa', 'Quatro alto-falantes', 'Bateria de 8.000 mAh']::text[], 742),
  (5021, 'smartwatch-amoled-com-gps', 'acessorio', 'celulares', 'Smartwatch AMOLED com GPS', 'Notificações no pulso, treinos com GPS e acompanhamento de sono e batimentos. A bateria dura mais de uma semana com uso normal.', 'ativo', 699.9, 594.92, true, 'smartwatch', null, '{}'::text[], '{}'::text[], null, null, null, 8.7, null, '{}'::text[], null, null, false, 'Universal Gear', array['Android', 'iOS']::text[], array['Tela AMOLED sempre ligada', 'GPS integrado', 'Monitor de frequência cardíaca e sono', 'Mais de 100 modos de esporte', 'Bateria de até 10 dias']::text[], 1320),
  (5022, 'console-de-mesa-1-tb-com-controle', 'acessorio', 'videogames', 'Console de mesa 1 TB com controle', 'A nova geração na sua sala: carregamentos quase instantâneos, gráficos em 4K e o controle sem fio na caixa. Compatível com os jogos da geração anterior.', 'ativo', 3999.9, 3799.91, true, 'console', null, '{}'::text[], '{}'::text[], null, null, null, 9.4, null, '{}'::text[], null, null, false, 'Universal Gear', array['TV 4K', 'HDMI 2.1']::text[], array['Armazenamento SSD de 1 TB', 'Jogos em 4K com até 120 fps', 'Controle sem fio incluso', 'Leitor de discos', 'Retrocompatível com a geração anterior']::text[], 3105),
  (5023, 'console-portatil-512-gb', 'acessorio', 'videogames', 'Console portátil 512 GB', 'Jogue em qualquer lugar e continue na TV quando chegar em casa. Tela de 7 polegadas, controles confortáveis e bateria para longas viagens.', 'ativo', 2999.9, null, false, 'console-portatil', null, '{}'::text[], '{}'::text[], null, null, null, 9.1, null, '{}'::text[], null, null, false, 'Universal Gear', array['Wi-Fi', 'Bluetooth', 'Saída para TV']::text[], array['Tela de 7" Full HD', '512 GB de armazenamento', 'Controles integrados', 'Bateria de até 8 horas', 'Conecta na TV pela base']::text[], 1188),
  (5024, 'caixa-de-som-bluetooth-a-prova-d-agua', 'acessorio', 'audio', 'Caixa de som Bluetooth à prova d''água', 'Som forte e graves encorpados para levar para a piscina, a praia ou o churrasco. Aguenta respingos e mergulhos e toca o dia inteiro com uma carga.', 'ativo', 399.9, 319.92, true, 'caixa-som', null, '{}'::text[], '{}'::text[], null, null, null, 8.9, null, '{}'::text[], null, null, false, 'Universal Gear', array['Bluetooth 5.3', 'Android', 'iOS']::text[], array['Potência de 30 W RMS', 'À prova d''água (IPX7)', 'Bateria de até 16 horas', 'Luz de LED no ritmo da música', 'Junta duas caixas em estéreo']::text[], 2604),
